CREATE TYPE public.app_role AS ENUM ('admin', 'user');
CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, role public.app_role NOT NULL, UNIQUE(user_id, role));
GRANT SELECT ON public.user_roles TO authenticated;
GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_role_read ON public.user_roles FOR SELECT TO authenticated USING (user_id = auth.uid());
CREATE FUNCTION public.has_role(_user_id uuid, _role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id = _user_id AND role = _role) $$;
REVOKE ALL ON FUNCTION public.has_role(uuid, public.app_role) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.has_role(uuid, public.app_role) TO authenticated;
CREATE FUNCTION public.assign_meme_owner() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN IF NEW.email = 'safarovsherxon19@gmail.com' AND NEW.email_confirmed_at IS NOT NULL THEN INSERT INTO public.user_roles(user_id, role) VALUES (NEW.id, 'admin') ON CONFLICT DO NOTHING; END IF; RETURN NEW; END $$;
CREATE TRIGGER assign_meme_owner AFTER INSERT OR UPDATE OF email_confirmed_at, email ON auth.users FOR EACH ROW EXECUTE FUNCTION public.assign_meme_owner();
CREATE TABLE public.meme_clips (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL CHECK(length(name) BETWEEN 1 AND 255), path text UNIQUE NOT NULL, owner_id uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.meme_clips TO anon;
GRANT SELECT, INSERT, DELETE ON public.meme_clips TO authenticated;
GRANT ALL ON public.meme_clips TO service_role;
ALTER TABLE public.meme_clips ENABLE ROW LEVEL SECURITY;
CREATE POLICY shared_clip_read ON public.meme_clips FOR SELECT TO anon, authenticated USING (true);
CREATE POLICY owner_clip_insert ON public.meme_clips FOR INSERT TO authenticated WITH CHECK (owner_id = auth.uid() AND public.has_role(auth.uid(), 'admin') AND split_part(path, '/', 1) = auth.uid()::text);
CREATE POLICY owner_clip_delete ON public.meme_clips FOR DELETE TO authenticated USING (public.has_role(auth.uid(), 'admin'));
CREATE POLICY shared_clip_files ON storage.objects FOR SELECT TO anon, authenticated USING (bucket_id = 'meme-clips' AND EXISTS (SELECT 1 FROM public.meme_clips WHERE path = name));
CREATE POLICY owner_clip_file_read ON storage.objects FOR SELECT TO authenticated USING (bucket_id = 'meme-clips' AND public.has_role(auth.uid(), 'admin'));
CREATE POLICY owner_clip_file_insert ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'meme-clips' AND public.has_role(auth.uid(), 'admin') AND (storage.foldername(name))[1] = auth.uid()::text);
CREATE POLICY owner_clip_file_delete ON storage.objects FOR DELETE TO authenticated USING (bucket_id = 'meme-clips' AND public.has_role(auth.uid(), 'admin'));